def _slug(title):
    return title.lower().replace(' ', '-').replace('&', 'and').replace('/', '-')


def _lesson_question(title, content, correct, distractors, explanation):
    options=[correct]+distractors
    return QuizQuestion(question=f"Which statement is most consistent with the guidance in '{title}'?", options=json.dumps(options), correct_index=0, explanation=explanation)


def _lesson_scenario(title, prompt, correct, alternatives, explanation):
    choices=[correct]+alternatives
    return Scenario(prompt=prompt, choices=json.dumps(choices), correct_index=0, explanation=explanation)


def _reconcile_course(course_data):
    course=Course.query.filter_by(title=course_data['title']).first()
    if not course:
        course=Course(title=course_data['title'], slug=_slug(course_data['title']), description=course_data['description'])
        db.session.add(course); db.session.flush()
    else:
        course.description=course_data['description']; course.slug=_slug(course_data['title'])
    for mi,(module_title, lessons) in enumerate(course_data['modules'],1):
        module=Module.query.filter_by(course_id=course.id,position=mi).first()
        if not module:
            module=Module(course_id=course.id,position=mi,title=module_title); db.session.add(module); db.session.flush()
        else: module.title=module_title
        for li,data in enumerate(lessons,1):
            title,content,detail,example,takeaways=data
            lesson=Lesson.query.filter_by(module_id=module.id,position=li).first()
            if not lesson:
                lesson=Lesson(module_id=module.id,position=li,title=title,objectives='',content='',examples='',takeaways=''); db.session.add(lesson); db.session.flush()
            lesson.title=title
            lesson.objectives="By the end of this lesson, the learner should be able to explain the main idea, recognise its practical warning signs and choose an appropriate safer response."
            lesson.content=content+"\n\n"+detail; lesson.examples=example; lesson.takeaways=takeaways
            correct=takeaways
            distractors=["Ignore the lesson guidance and act immediately when the situation feels urgent.","Share sensitive information first and verify the situation afterwards.","Assume the situation is safe because it looks familiar or professional."]
            q=lesson.questions[0] if lesson.questions else None
            if not q: q=_lesson_question(title,content,correct,distractors,f"The lesson on {title} specifically teaches: {takeaways}"); q.lesson_id=lesson.id; db.session.add(q)
            else:
                q.question=f"Which statement is most consistent with the guidance in '{title}'?"; q.options=json.dumps([correct]+distractors); q.correct_index=0; q.explanation=f"The lesson on {title} specifically teaches: {takeaways}"
            sc=Scenario.query.filter_by(lesson_id=lesson.id).first()
            alternatives=["Act immediately without checking whether the situation is legitimate or safe.","Provide sensitive information first and investigate only if something goes wrong.","Treat the situation as trustworthy simply because the message, person or service looks familiar."]
            if not sc: sc=_lesson_scenario(title,example,takeaways,alternatives,f"A safer response for {title} follows the lesson guidance: {takeaways}"); sc.lesson_id=lesson.id; db.session.add(sc)
            else:
                sc.prompt=example; sc.choices=json.dumps([takeaways]+alternatives); sc.correct_index=0; sc.explanation=f"A safer response for {title} follows the lesson guidance: {takeaways}"
    return course


def seed_database():
    for data in COURSE_DATA: _reconcile_course(data)
    db.session.commit()
